SELECT * FROM (SELECT e.event_id,'H:'||s.handling_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':start' event_id,'Unloading Started' activity,started_at timestamp,handling_id source_key FROM handling_history WHERE started_at IS NOT NULL AND (handling_code='U')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.handling_id IS NOT NULL UNION ALL SELECT e.event_id,'H:'||s.handling_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':complete' event_id,'Unloading Completed' activity,completed_at timestamp,handling_id source_key FROM handling_history WHERE completed_at IS NOT NULL AND (handling_code='U')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.handling_id IS NOT NULL UNION ALL SELECT e.event_id,'H:'||s.handling_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':start' event_id,'Loading Started' activity,started_at timestamp,handling_id source_key FROM handling_history WHERE started_at IS NOT NULL AND (handling_code='L')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.handling_id IS NOT NULL UNION ALL SELECT e.event_id,'H:'||s.handling_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':complete' event_id,'Loading Completed' activity,completed_at timestamp,handling_id source_key FROM handling_history WHERE completed_at IS NOT NULL AND (handling_code='L')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.handling_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
